INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 91, "", "", 13020014, 13020011, "", "", 302, "", "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 11, "いかんいかん\n資材の山に埋もれて\nしまうところだった", "", 13020015, 111031, "", "", 302, "", 10);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 91, "", "", 13020016, 0, "", "", 302, "", "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 3, "nyx_302_yuni_02", 1, 13020017, 2, "NoItem", "", 302, 0.2, 0);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES (0.2, 3, "nyx_302_yuni_02", 1, 13020018, 111031, "nyx_idle_normal", "", 302, 0.2, 0);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 11, "だが怪我の功名、\n探していた部品を\n偶然にも発見できた", "", 13020019, 111031, "", "", 302, "", 10);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 93, "", "", 13020020, 5, "", "", 302, "", "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 4, 0, "", 13020021, 111031, "", "", 302, "", "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 3, "nyx_cmn_03", "", 13020022, 111031, "", "", 302, 0.2, 1);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 11, "ふむ…これは僥倖\nかくなる上は再び\n潜航してみるか…", "", 13020023, 111031, "", "", 302, "", 10);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 91, "", "", 13020024, 0, "", "", 302, "", "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 3, "nyx_301_yuni_01", "", 13020025, 111031, "", "", 302, 0.2, 1);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 11, "存外意義あるものだ\n資材ダイビングとか\nいう新種の探索行は", "", 13020026, 111031, "", "", 302, "", 10);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 91, 1, "", 13020027, 0, "", "", 302, "", "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 11, "まあ万一溺れたとて\n後輩たちの誰ぞが\nきっと気付くだろう", "", 13020028, 111031, "", "", 302, "", 10);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 91, 1, "", 13020029, 0, "", "", 302, "", "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 3, "nyx_302_yuni_03", 1, 13020030, 111031, "nyx_302_yuni_04", "", 302, 0.2, 0);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 11, "是非もなし\nいざ往かん！", "", 13020031, 111031, "", "", 302, "", 10);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 91, 1, "", 13020032, 0, "", "", 302, "", "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 93, "", "", 13020033, 1.5, "", "", 302, "", "");
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 11, "む。奥に入りすぎた\nこれは…出られぬ！\n誰かー！　誰か―！", "", 13020034, 111031, "", "", 302, "", 10);
INSERT INTO `v1_3d4fe1be70ab128ff2cfc4bafbc5bd005d82cd6fcc726ec2e3dba1aaea7baa7c` VALUES ("", 91, "", "", 13020035, 0, "", "", 302, "", "");
